#!/usr/bin/env node
/**
 * Writes src/environments/environment.e2e.ts for the non-production E2E build. Shared by both
 * repos — keep the two copies identical (listed in parity/shared-files.json).
 *
 *   E2E_API_URL=https://api.<e2e-domain>/api E2E_BASE_DOMAIN=<e2e-domain> npm run build:e2e
 *
 * Fails closed: the build stops unless both variables are set, the API is https, and neither
 * value is a production (edunexify.co.in), localhost or IP-literal host. The generated file is
 * gitignored, so no E2E host is ever committed and the production environments stay untouched.
 */
import { writeFileSync } from 'node:fs';

const PRODUCTION_DOMAIN = 'edunexify.co.in';

const fail = (message) => {
  console.error(`e2e environment: ${message}`);
  process.exit(1);
};

const isProductionHost = (host) => host === PRODUCTION_DOMAIN || host.endsWith(`.${PRODUCTION_DOMAIN}`);
const isLocalOrIp = (host) =>
  host === 'localhost' || host.endsWith('.localhost') || /^\d{1,3}(\.\d{1,3}){3}$/.test(host) || host.includes(':');

const rawApiUrl = (process.env.E2E_API_URL ?? '').trim();
const baseDomain = (process.env.E2E_BASE_DOMAIN ?? '').trim().toLowerCase();

if (!rawApiUrl) fail('E2E_API_URL is not set (expected https://<non-prod host>/api).');
if (!baseDomain) fail('E2E_BASE_DOMAIN is not set (expected the non-prod school domain, e.g. e2e-domain.example).');

let api;
try {
  api = new URL(rawApiUrl);
} catch {
  fail(`E2E_API_URL is not a valid URL: ${rawApiUrl}`);
}
const apiHost = api.hostname.toLowerCase();

if (api.protocol !== 'https:') fail('E2E_API_URL must use https.');
if (isProductionHost(apiHost)) fail(`E2E_API_URL points at production (${apiHost}).`);
if (isLocalOrIp(apiHost)) fail(`E2E_API_URL must be a real hostname, not localhost or an IP (${apiHost}).`);
if (api.search || api.hash) fail('E2E_API_URL must not contain a query or fragment.');
const apiUrl = `${api.origin}${api.pathname.replace(/\/+$/, '')}`;
if (!apiUrl.endsWith('/api')) fail(`E2E_API_URL must end with /api (got ${apiUrl}).`);

if (!/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$/.test(baseDomain)) {
  fail(`E2E_BASE_DOMAIN must be a bare domain name (got ${baseDomain}).`);
}
if (isProductionHost(baseDomain)) fail(`E2E_BASE_DOMAIN is production (${baseDomain}).`);
if (isLocalOrIp(baseDomain)) fail(`E2E_BASE_DOMAIN must be a real domain, not localhost or an IP (${baseDomain}).`);

const environment = { production: false, apiUrl, baseDomain };
writeFileSync(
  'src/environments/environment.e2e.ts',
  '// GENERATED by scripts/generate-e2e-environment.mjs for the non-production E2E build.\n'
    + '// Do not edit or commit — set E2E_API_URL and E2E_BASE_DOMAIN and rebuild instead.\n'
    + `export const environment = ${JSON.stringify(environment, null, 2)};\n`,
);
console.log(`e2e environment: apiUrl=${apiUrl} baseDomain=${baseDomain}`);
